class Solution {
public:
    long long maxScore(std::vector<std::vector<int>>& edges) {
        int n = edges.size();
        std::vector<std::vector<std::pair<int, int>>> adj(n);
        for (int i = 0; i < n; ++i) {
            if (edges[i][0] != -1) {
                adj[edges[i][0]].push_back({i, edges[i][1]});
            }
        }
        auto dfs = [&](auto& self, int u) -> std::pair<long long, long long> {
            long long base = 0, diff = 0;
            for (const auto& [v, w] : adj[u]) {
                auto [v0, v1] = self(self, v);
                base += v1;
                diff = std::max(diff, (long long)w + v0 - v1);
            }
            return {base, base + diff};
        };
        return dfs(dfs, 0).second;
    }
};

class Solution {
    public long maxScore(int[][] edges) {
        int n = edges.length;
        java.util.List<int[]>[] adj = new java.util.ArrayList[n];
        for (int i = 0; i < n; ++i) adj[i] = new java.util.ArrayList<>();
        for (int i = 0; i < n; ++i) {
            if (edges[i][0] != -1) {
                adj[edges[i][0]].add(new int[]{i, edges[i][1]});
            }
        }
        return dfs(0, adj)[1];
    }
    private long[] dfs(int u, java.util.List<int[]>[] adj) {
        long base = 0, diff = 0;
        for (int[] edge : adj[u]) {
            int v = edge[0], w = edge[1];
            long[] child = dfs(v, adj);
            base += child[1];
            diff = Math.max(diff, (long) w + child[0] - child[1]);
        }
        return new long[]{base, base + diff};
    }
}

var maxScore = function(edges) {
    const n = edges.length;
    const adj = Array.from({ length: n }, () => []);
    for (let i = 0; i < n; ++i) {
        if (edges[i][0] !== -1) {
            adj[edges[i][0]].push([i, edges[i][1]]);
        }
    }
    function dfs(u) {
        let base = 0n, diff = 0n;
        for (const [v, w] of adj[u]) {
            const [v0, v1] = dfs(v);
            base += v1;
            const cand = BigInt(w) + v0 - v1;
            if (cand > diff) diff = cand;
        }
        return [base, base + diff];
    }
    return Number(dfs(0)[1]);
};
